  '1.3.6.1.4.1.2011.5.4.2.2.1.1': { name: 'hwPortalServerUp', label: '探测到Portal服务器由down状态变为up状…', detail: '探测到Portal服务器由down状态变为up状态，产生trap。' },
  '1.3.6.1.4.1.2011.5.4.2.2.1.2': { name: 'hwPortalServerDown', label: '探测到Portal服务器由up状态变为down状…', detail: '探测到Portal服务器由up状态变为down状态，产生trap。' },
