  '1.3.6.1.4.1.2011.5.4.2.2.1.5': { name: 'hwPortalPassDNS', label: '开启Portal认证时设备放通DNS报文功能', detail: '开启Portal认证时设备放通DNS报文功能，产生告警。' },
