  '1.3.6.1.4.1.2011.5.12.7.1.4.1': { name: 'hwMplsPsSwitchPtoW', label: '数据流从保护组的备tunnel倒换到主tunne…', detail: '数据流从保护组的备tunnel倒换到主tunnel上传输。' },
