  '1.3.6.1.4.1.2011.5.25.19.2.1': { name: 'hwSysClockChangedNotification', label: '系统时钟改变通知', detail: '系统时钟改变通知，当系统时钟改变时将触发该TRAP。如通过命令行改变系统时钟。' },
  '1.3.6.1.4.1.2011.5.25.19.2.2': { name: 'hwSysReloadNotification', label: '系统重启通知' },
