  '1.3.6.1.4.1.2011.5.25.136.1.6.38': { name: 'hwDot1agCfmUnexpectedPeriod', label: '两端OAM实体配置的802.1ag满足： MEG…', detail: '当两端OAM实体配置的802.1ag满足： MEG的级别一致； MA ID正确； CCM报文携带的MEPID在本端配置RMEP列表中； 接收使能； 情况时，如果两端配置的CMM报文时间间隔不一致，则上报告警。' },
  '1.3.6.1.4.1.2011.5.25.136.1.6.39': { name: 'hwDot1agCfmUnexpectedPeriodCleared', label: '当两端OAM实体配置的802.1ag满足： ME…', detail: '当两端OAM实体配置的802.1ag满足： MEG的级别一致； MA ID正确； CCM报文携带的MEPID在本端配置RMEP列表中； 接收使能； 情况时，如果两端配置的CMM报文时间间隔不一致时上报的告警清除。' },
  '1.3.6.1.4.1.2011.5.25.136.1.6.40': { name: 'hwDot1agCfmUnexpectedMAC', label: '两端OAM实体配置的802.1ag满足 MEG的…', detail: '两端OAM实体配置的802.1ag满足 MEG的级别一致； MAID都正确； CCM报文携带的MEPID在本端配置RMEP列表中； 接收使能； 两端配置的CMM报文时间间隔一致。 情况时，如果本端配置的RMEP绑定的MAC地址与CCM报文中携带的对端设备的MAC地址不一致，则上报告警。' },
  '1.3.6.1.4.1.2011.5.25.136.1.6.41': { name: 'hwDot1agCfmUnexpectedMACCleared', label: '两端OAM实体配置的802.1ag满足 MEG的…', detail: '两端OAM实体配置的802.1ag满足 MEG的级别一致； MAID都正确； CCM报文携带的MEPID在本端配置RMEP列表中； 接收使能； 两端配置的CMM报文时间间隔一致。 情况时，如果本端配置的RMEP绑定的MAC地址与CCM报文中携带的对端设备的MAC地址不一致时上报的告警清除。' },
