  '1.3.6.1.6.3.1.1.5.3': { name: 'linkDown', label: '链路断开', detail: 'linkDown告警表示：作为代理的SNMP实体已经检测到由于ifOperStatus节点中的其中一条通信链路已经从其他状态（但不是notPresent状态）进入Down状态。这里的其他状态由ifOperStatus的值显示。' },
  '1.3.6.1.6.3.1.1.5.4': { name: 'linkUp', label: '链路恢复', detail: 'linkUp告警表示：作为代理的SNMP实体已经检测到由于ifOperStatus节点中的其中一条通信链路已经从Down状态转变为其他状态（但不是notPresent状态）。这里的其他状态由ifOperStatus的值显示' },
